CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_department_summary` AS select `d`.`department_id` AS `department_id`,`d`.`department_name` AS `department_name`,count(`e`.`employee_id`) AS `employee_count`,coalesce(avg(`e`.`salary`),0) AS `average_salary`,coalesce(max(`e`.`salary`),0) AS `maximum_salary`,coalesce(min(`e`.`salary`),0) AS `minimum_salary` from (`departments` `d` left join `employees` `e` on((`d`.`department_id` = `e`.`department_id`))) group by `d`.`department_id`,`d`.`department_name`;
